.hm-venue{gap:4px}.hm-venue-heading{display:flex;align-items:center;justify-content:space-between}.hm-venue-heading>text:first-child{font-size:17px;line-height:22px;letter-spacing:-.17px;font-weight:600}.hm-venue-heading>text:last-child{flex:none;padding:2px 8px;border-radius:4px;background:#efedf3;color:#424655;font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,"Liberation Mono","Courier New",monospace;font-size:11px;line-height:14px;letter-spacing:.22px;font-weight:700}.hm-map{position:relative;overflow:hidden;width:100%;height:128px;margin-top:8px;border-radius:8px}.hm-map>image,.hm-map-scrim{position:absolute;inset:0;width:100%;height:100%}.hm-map-scrim{background:linear-gradient(to top,rgba(0,0,0,.6),transparent,transparent)}.hm-map-copy{position:absolute;left:10px;right:10px;bottom:10px;display:flex;flex-direction:column;color:#fff}.hm-map-copy>text:first-child{font-size:15px;line-height:20px;font-weight:700}.hm-map-copy>text:last-child{font-size:13px;line-height:18px;font-weight:400;opacity:.9}.hm-terminal{display:flex;flex-direction:column;align-items:center;justify-content:center;padding:4px 0 8px}.hm-terminal>view{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:8px 16px;border-radius:9999px;background:#efedf3;color:#424655;font-size:13px;line-height:16px;font-weight:600;letter-spacing:-.325px}.hm-terminal image{width:16px;height:16px}.hm-terminal>text{margin-top:6px;color:#737687;font-size:11px;line-height:14px;letter-spacing:.22px;font-weight:700}
